final class BossProgress {
    // Named counters are facts exposed by the RuneLite game API. Do not guess unmapped IDs.
    static void append(Client client, ConfigManager config, JsonObject snapshot) {
        JsonObject game = new JsonObject();
        JsonObject cache = new JsonObject();
        RuneScapeProfileType mode = RuneScapeProfileType.getCurrent(client);
        snapshot.addProperty("profile_mode", mode.name());
        if (mode == RuneScapeProfileType.STANDARD) {
            add(game, client, VarPlayerID.TOTAL_COMPLETED_GAUNTLET, "The Gauntlet");
            add(game, client, VarPlayerID.TOTAL_COMPLETED_GAUNTLET_HM, "The Corrupted Gauntlet");
            add(game, client, VarPlayerID.TOTAL_ABYSSALSIRE_KILLS, "abyssal sire");
            add(game, client, VarPlayerID.TOTAL_AMOXLIATL_KILLS, "amoxliatl");
            add(game, client, VarPlayerID.TOTAL_ARAXXOR_KILLS, "araxxor");
            add(game, client, VarPlayerID.TOTAL_ARMADYL_KILLS, "kree'arra");
            add(game, client, VarPlayerID.TOTAL_ARTIO_KILLS, "artio");
            add(game, client, VarPlayerID.TOTAL_BANDOS_KILLS, "general graardor");
            add(game, client, VarPlayerID.TOTAL_BRYOPHYTA_KILLS, "bryophyta");
            add(game, client, VarPlayerID.TOTAL_CALLISTO_KILLS, "callisto");
            add(game, client, VarPlayerID.TOTAL_CALVARION_KILLS, "calvar'ion");
            add(game, client, VarPlayerID.TOTAL_CERBERUS_KILLS, "cerberus");
            add(game, client, VarPlayerID.TOTAL_CHAOSELE_KILLS, "chaos elemental");
            add(game, client, VarPlayerID.TOTAL_CHAOSFANATIC_KILLS, "chaos fanatic");
