            add(game, client, VarPlayerID.TOTAL_DERANGEDARCHAEOLOGIST_KILLS, "deranged archaeologist");
            add(game, client, VarPlayerID.TOTAL_DUKE_SUCELLUS_AWAKENED_KILLS, "duke sucellus (awakened)");
            add(game, client, VarPlayerID.TOTAL_DUKE_SUCELLUS_KILLS, "duke sucellus");
            add(game, client, VarPlayerID.TOTAL_GARGBOSS_KILLS, "grotesque guardians");
            add(game, client, VarPlayerID.TOTAL_HESPORI_KILLS, "hespori");
            add(game, client, VarPlayerID.TOTAL_HILLGIANT_BOSS_KILLS, "obor");
            add(game, client, VarPlayerID.TOTAL_HUEY_KILLS, "The Hueycoatl");
            add(game, client, VarPlayerID.TOTAL_HYDRABOSS_KILLS, "alchemical hydra");
            add(game, client, VarPlayerID.TOTAL_JAD_KILLS, "tztok-jad");
            add(game, client, VarPlayerID.TOTAL_KALPHITE_KILLS, "kalphite queen");
            add(game, client, VarPlayerID.TOTAL_KBD_KILLS, "king black dragon");
            add(game, client, VarPlayerID.TOTAL_KRAKEN_BOSS_KILLS, "kraken");
            add(game, client, VarPlayerID.TOTAL_LEVIATHAN_AWAKENED_KILLS, "leviathan (awakened)");
