            add(game, client, VarPlayerID.TOTAL_VARDORVIS_KILLS, "vardorvis");
            add(game, client, VarPlayerID.TOTAL_VENENATIS_KILLS, "venenatis");
            add(game, client, VarPlayerID.TOTAL_VETION_KILLS, "vet'ion");
            add(game, client, VarPlayerID.TOTAL_VORKATH_KILLS, "vorkath");
            add(game, client, VarPlayerID.TOTAL_WHISPERER_AWAKENED_KILLS, "whisperer (awakened)");
            add(game, client, VarPlayerID.TOTAL_WHISPERER_KILLS, "The Whisperer");
            add(game, client, VarPlayerID.TOTAL_WINTERTODT_KILLS, "wintertodt");
            add(game, client, VarPlayerID.TOTAL_YAMA_KILLS, "yama");
            add(game, client, VarPlayerID.TOTAL_ZALCANO_KILLS, "zalcano");
            add(game, client, VarPlayerID.TOTAL_ZAMORAK_KILLS, "k'ril tsutsaroth");
            add(game, client, VarPlayerID.TOTAL_ZUK_KILLS, "tzkal-zuk");
        }
        String key = config.getRSProfileKey();
        long account = client.getAccountHash();
        if (key != null && account != -1L && mode == RuneScapeProfileType.STANDARD) {
            for (RuneScapeProfile profile : config.getRSProfiles()) {
                if (key.equals(profile.getKey()) && account == profile.getAccountHash() && mode == profile.getType()) {
                    for (String boss : config.getRSProfileConfigurationKeys("killcount", key, "")) {
                        if (boss.isBlank() || boss.length() > 100) continue;
                        // Read only the verified profile and only the kill-count group.
                        Integer kc = config.getConfiguration("killcount", key, boss, Integer.class);
                        if (kc != null && kc >= 0) cache.addProperty(boss, kc);
                    }
                    break;
                }
            }
        }
        snapshot.add("kill_counts_game", game);
        snapshot.add("kill_counts_local_cache", cache);
    }

    private static void add(JsonObject game, Client client, int id, String boss) {
        int value = client.getVarpValue(id);
        // A zero may also mean a counter was not sent to this client. A recorded
        // zero from the local kill-log cache is distinct from missing evidence.
        if (value > 0) game.addProperty(boss, value);
    }
}

package com.localprogressnotes;

import java.util.Map;
import java.util.TreeMap;

/** Collect the unique positive item IDs from one explicit, local search. */
final class CollectionCapture {
    // Script arguments exposed by the live game-client collection search.
    static final int ITEM_RESULT = 4100;
    static final int SEARCH_SETUP = 2240;
    private static final int WAIT_TICKS = 6;
    private static final int QUIET_TICKS = 2;
    private final Map<Integer, Integer> items = new TreeMap<>();
    private final int expected;
    private int ticks;
    private int lastFound = -1;

    CollectionCapture(int expected) {
        this.expected = expected;
    }

    void observe(int script, Object[] args) {
        if (script != ITEM_RESULT || args == null || args.length < 3
            || !(args[1] instanceof Integer) || !(args[2] instanceof Integer)) return;
        int id = (int)args[1];
        int quantity = (int)args[2];
        if (id <= 0 || items.size() >= 5000) return;
        items.merge(id, Math.max(0, quantity), Math::max);
        lastFound = ticks;
    }

    boolean advance() {
        ++ticks;
        return ticks >= WAIT_TICKS || (lastFound >= 0 && ticks - lastFound >= QUIET_TICKS);
    }

    boolean hasResult() {
        return !items.isEmpty() || expected == 0;
    }

    Map<Integer, Integer> items() {
        return Map.copyOf(items);
    }

    int expected() {
        return expected;
    }
}

package com.localprogressnotes;

import java.io.IOException;
import java.nio.file.attribute.FileTime;
import java.util.Iterator;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

/** Resolve only an existing generated dashboard in this plugin's local folder. */
final class DashboardActions {
    private static final Pattern NAME = Pattern.compile("dashboard-[a-z0-9 ]{1,12}(?:--[a-z_]{1,30})?\\.html");

    private DashboardActions() { }

    static Filepath latest(Filepath folder) throws IOException {
        if (!folder.isDirectory()) return null;
        Filepath latest = null;
        FileTime modified = null;
        try (Stream<Filepath> entries = folder.walk(1)) {
            Iterator<Filepath> files = entries.iterator();
            while (files.hasNext()) {
                Filepath file = files.next();
                if (file.equals(folder) || !NAME.matcher(file.getFileName()).matches() || !file.isFile()) continue;
                FileTime time = file.getLastModifiedTime();
                if (latest == null || time.compareTo(modified) > 0
                    || time.equals(modified) && file.compareTo(latest) > 0) {
                    latest = file;
                    modified = time;
                }
            }
        }
        return latest;
    }
}

package com.localprogressnotes;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.function.IntUnaryOperator;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/** Reads only the open local journal; no scripts, input, network, or reflection. */
final class DiaryJournal {
    private static final String[] TIERS = {"easy", "medium", "hard", "elite"};
    private static final Pattern TOKEN = Pattern.compile("(?i)<br\\s*/?>|\\r\\n|\\n|\\r|</?str(?:=[0-9a-f]{1,8})?>|<[^>]{1,100}>");
    private static final Pattern HEADING = Pattern.compile("^(easy|medium|hard|elite)(?: (?:diary|tasks)){0,2}(?: [0-9]+(?: [0-9]+)?(?: tasks)?)?$");
    // Opening verbs in the bundled diary checklist. Keep them as boundaries
    // when a native line wraps onto a capitalized name rather than a lowercase word.
    private static final Set<String> TASK_STARTS = Set.of(
        ("activate attempt bake be become board browse build burn buy cast catch change charge charter check chop claim climb collect "
        + "complete construct cook crack craft create cremate cross cut defeat deliver dig discover do earn eat enter equip exchange "
        + "explore fertilize fill find fish fletch get give go grapple grow hand harvest have imbue jump kill knock learn light loot "
        + "make mine mix obtain offer open perform pick picklock pickpocket place plant play pray purchase read recharge refill repair "
        + "restore score select sell slay smelt smith speak spin squeeze steal string subdue switch take talk telegrab teleport trade trap "
        + "travel turn unlock use view visit").split(" "));
    private enum Layout { LEGACY_MERGE, LEGACY_SPLIT, NATIVE }
    private static final Area[] AREAS = {
        new Area("Ardougne", "Ardougne", new int[]{10, 12, 12, 8}, new int[]{VarbitID.ARDOUGNE_EASY_COUNT, VarbitID.ARDOUGNE_MED_COUNT, VarbitID.ARDOUGNE_HARD_COUNT, VarbitID.ARDOUGNE_ELITE_COUNT}),
        new Area("Desert", "Desert", new int[]{11, 12, 10, 6}, new int[]{VarbitID.DESERT_EASY_COUNT, VarbitID.DESERT_MED_COUNT, VarbitID.DESERT_HARD_COUNT, VarbitID.DESERT_ELITE_COUNT}),
        new Area("Falador", "Falador", new int[]{11, 14, 11, 6}, new int[]{VarbitID.FALADOR_EASY_COUNT, VarbitID.FALADOR_MED_COUNT, VarbitID.FALADOR_HARD_COUNT, VarbitID.FALADOR_ELITE_COUNT}),
        new Area("Fremennik", "Fremennik", new int[]{10, 9, 9, 6}, new int[]{VarbitID.FREMENNIK_EASY_COUNT, VarbitID.FREMENNIK_MED_COUNT, VarbitID.FREMENNIK_HARD_COUNT, VarbitID.FREMENNIK_ELITE_COUNT}),
        new Area("Kandarin", "Kandarin", new int[]{11, 14, 11, 7}, new int[]{VarbitID.KANDARIN_EASY_COUNT, VarbitID.KANDARIN_MED_COUNT, VarbitID.KANDARIN_HARD_COUNT, VarbitID.KANDARIN_ELITE_COUNT}),
        new Area("Karamja", "Karamja", new int[]{10, 19, 10, 5}, new int[]{VarbitID.KARAMJA_EASY_COUNT, VarbitID.KARAMJA_MED_COUNT, VarbitID.KARAMJA_HARD_COUNT, VarbitID.KARAMJA_ELITE_COUNT}),
        new Area("Kourend & Kebos", "Kourend", new int[]{12, 13, 10, 8}, new int[]{VarbitID.KOUREND_EASY_COUNT, VarbitID.KOUREND_MED_COUNT, VarbitID.KOUREND_HARD_COUNT, VarbitID.KOUREND_ELITE_COUNT}),
        new Area("Lumbridge & Draynor", "Lumbridge", new int[]{12, 12, 11, 6}, new int[]{VarbitID.LUMBRIDGE_EASY_COUNT, VarbitID.LUMBRIDGE_MED_COUNT, VarbitID.LUMBRIDGE_HARD_COUNT, VarbitID.LUMBRIDGE_ELITE_COUNT}),
        new Area("Morytania", "Morytania", new int[]{11, 11, 10, 6}, new int[]{VarbitID.MORYTANIA_EASY_COUNT, VarbitID.MORYTANIA_MED_COUNT, VarbitID.MORYTANIA_HARD_COUNT, VarbitID.MORYTANIA_ELITE_COUNT}),
        new Area("Varrock", "Varrock", new int[]{14, 13, 10, 5}, new int[]{VarbitID.VARROCK_EASY_COUNT, VarbitID.VARROCK_MED_COUNT, VarbitID.VARROCK_HARD_COUNT, VarbitID.VARROCK_ELITE_COUNT}),
        new Area("Western Provinces", "Western", new int[]{11, 13, 13, 7}, new int[]{VarbitID.WESTERN_EASY_COUNT, VarbitID.WESTERN_MED_COUNT, VarbitID.WESTERN_HARD_COUNT, VarbitID.WESTERN_ELITE_COUNT}),
        new Area("Wilderness", "Wilderness", new int[]{12, 11, 10, 7}, new int[]{VarbitID.WILDERNESS_EASY_COUNT, VarbitID.WILDERNESS_MED_COUNT, VarbitID.WILDERNESS_HARD_COUNT, VarbitID.WILDERNESS_ELITE_COUNT})
    };

    private DiaryJournal() { }

    static final class Area {
        final String name;
        final String shortName;
        final int[] expected, countVars;
        Area(String name, String shortName, int[] expected, int[] countVars) {
            this.name = name; this.shortName = shortName; this.expected = expected; this.countVars = countVars;
        }
    }

    static final class Task {
        final String text;
        final boolean complete;
        final boolean explicitStyle;
        Task(String text, boolean complete) { this(text, complete, false); }
        Task(String text, boolean complete, boolean explicitStyle) {
            this.text = text; this.complete = complete; this.explicitStyle = explicitStyle;
        }
    }

    static final class Page {
        final Area area;
        final Map<Integer, List<Task>> tiers;
        Page(Area area, Map<Integer, List<Task>> tiers) {
            this.area = area; this.tiers = Collections.unmodifiableMap(new LinkedHashMap<>(tiers));
        }
        JsonObject current(IntUnaryOperator varbit) {
            JsonObject out = new JsonObject();
            for (Map.Entry<Integer, List<Task>> entry : tiers.entrySet()) {
                int tier = entry.getKey();
                List<Task> tasks = entry.getValue();
                if (!valid(area, tier, tasks, varbit)) continue;
                JsonArray rows = new JsonArray();
                for (Task task : tasks) {
                    JsonObject item = new JsonObject();
                    item.addProperty("text", task.text);
                    item.addProperty("complete", task.complete);
                    rows.add(item);
                }
                out.add(TIERS[tier], rows);
            }
            return out;
        }
    }

    static Page merge(Page previous, Page latest) {
        if (previous.area != latest.area) return latest;
        Map<Integer, List<Task>> merged = new LinkedHashMap<>(previous.tiers);
        merged.putAll(latest.tiers);
        return new Page(latest.area, merged);
    }

    static final class Frame {
        final String title;
        final List<List<String>> candidates;
        Frame(String title, List<List<String>> candidates) {
            this.title = title;
            this.candidates = List.copyOf(candidates);
        }
        boolean same(Frame previous) {
            return previous != null && title.equals(previous.title) && candidates.equals(previous.candidates);
        }
    }

    static final class ReadWindow {
        private static final int RETRY_TICKS = 3;
        private Frame last;
        private String owner;
        private int retry;
        private boolean same;
        void reset() { last=null;owner=null;retry=0; }
        boolean shouldRead(Frame current, String key) {
            if (current==null || key==null) { reset();return false; }
            same=key.equals(owner)&&current.same(last);
            if (same&&(retry<0||retry++<RETRY_TICKS)) return false;
            last=current;owner=key;return true;
        }
        void analyzed(Result result) {
            retry=same||result.page!=null&&result.page.tiers.size()==4?-1:0;
        }
    }

    static final class Result {
        final Page page;
        final String diagnostic;
        Result(Page page, String diagnostic) { this.page = page; this.diagnostic = diagnostic; }
    }

    static Frame frame(Client client) {
        Widget title = client.getWidget(InterfaceID.Journalscroll.TITLE);
        String raw = title == null || title.isHidden() ? "" : title.getText();
        if (!isDiary(raw)) return null;
        Widget body = client.getWidget(InterfaceID.Journalscroll.TEXTLAYER);
        if (body == null || body.isHidden()) return new Frame(raw, List.of());
        List<List<String>> candidateLists = new ArrayList<>();
        for (Widget[] children : new Widget[][] {body.getStaticChildren(), body.getDynamicChildren(), body.getChildren()}) {
            if (children == null || children.length == 0 || children.length > 250) continue;
            List<String> strings = new ArrayList<>();
            for (Widget child : children) {
                if (child != null && !child.isSelfHidden() && child.getText() != null) strings.add(child.getText());
            }
            if (!strings.isEmpty() && !candidateLists.contains(strings)) candidateLists.add(List.copyOf(strings));
        }
        if (body.getText() != null && !body.getText().isBlank()) candidateLists.add(List.of(body.getText()));
        return new Frame(raw, candidateLists);
    }

    static Result analyze(Frame frame, IntUnaryOperator varbit) {
        if (frame == null) return new Result(null, "Open a region’s Achievement Diary.");
        Area area = null;
        Map<Integer, List<Task>> verified = new LinkedHashMap<>();
        Set<Integer> conflicts = new HashSet<>();
        Map<Integer, List<Task>> nativeVerified = new LinkedHashMap<>();
        Set<Integer> nativeConflicts = new HashSet<>();
        String bestDiagnostic = null;
        int bestHeaders = 0;
        for (List<String> candidate : frame.candidates) {
            for (Layout layout : Layout.values()) {
                Attempt a = scan(frame.title, candidate, layout);
                if (a == null) continue;
                if (area != null && a.area != area) return new Result(null, "Diary region changed while reading. Try again.");
                area = a.area;
                if (a.rows.size() > bestHeaders) {
                    bestHeaders = a.rows.size();
                    List<String> parts = new ArrayList<>();
                    for (Map.Entry<Integer,List<Task>> e : a.rows.entrySet()) {
                        int tier = e.getKey();
                        if (a.invalid.contains(tier)) { parts.add(TIERS[tier] + " unclear"); continue; }
                        long struck=e.getValue().stream().filter(t->t.complete).count();
                        parts.add(TIERS[tier]+": "+e.getValue().size()+"/"+area.expected[tier]+" rows, "+struck+"/"+varbit.applyAsInt(area.countVars[tier])+" done");
                    }
                    bestDiagnostic = String.join("; ", parts);
                }
                for (Map.Entry<Integer,List<Task>> e : a.rows.entrySet()) {
                    int tier = e.getKey(); List<Task> tasks = e.getValue();
                    Map<Integer, List<Task>> results = layout == Layout.NATIVE ? nativeVerified : verified;
                    Set<Integer> disagreements = layout == Layout.NATIVE ? nativeConflicts : conflicts;
                    if (a.invalid.contains(tier) || disagreements.contains(tier) || !valid(area, tier, tasks, varbit)) continue;
                    if (results.containsKey(tier) && !sameTasks(results.get(tier), tasks)) {
                        results.remove(tier); disagreements.add(tier);
                    } else results.putIfAbsent(tier, List.copyOf(tasks));
                }
            }
        }
        if (area == null) return new Result(null, "Diary open, but no recognized region heading yet.");
        nativeConflicts.forEach(verified::remove);
        nativeVerified.forEach(verified::put);
        return new Result(verified.isEmpty() ? null : new Page(area, verified),
            area.name + (bestDiagnostic == null ? ": no tier headings." : " — " + bestDiagnostic));
    }

    static Page parse(String title, List<String> widgets, IntUnaryOperator varbit) {
        return analyze(new Frame(title, List.of(widgets)), varbit).page;
    }

    private static boolean sameTasks(List<Task> a,List<Task> b) {
        for(int i=0;i<a.size();i++) {
            if (a.get(i).complete!=b.get(i).complete || !normalize(a.get(i).text).equals(normalize(b.get(i).text))) return false;
        }
        return true;
    }

    private static final class Attempt {
        final Area area;
        final Map<Integer,List<Task>> rows;
        final Set<Integer> invalid;
        Attempt(Area a,Map<Integer,List<Task>> rows,Set<Integer> invalid) { this.area=a;this.rows=rows;this.invalid=invalid; }
    }

    private static boolean isDiary(String title) {
        final String journal = normalize(clean(title));
        return journal.equals("achievement diary") || journal.startsWith("achievement diary ");
    }

    private static Attempt scan(String title, List<String> widgets, Layout layout) {
        final String journal = normalize(clean(title));
        if (!isDiary(title)) return null;
        Area area = journal.equals("achievement diary") ? null : region(journal.substring("achievement diary ".length()));
        Map<Integer,List<Task>> raw = new LinkedHashMap<>();
        Set<Integer> invalid = new HashSet<>();
        int tier = -1;
        boolean afterReward = false;
        for (String widget : widgets) {
            if (widget == null || widget.length() > 30_000) continue;
            for (Task line : lines(widget, layout == Layout.NATIVE)) {
                String norm = normalize(line.text);
                if (norm.isEmpty()) continue;
                Area section = norm.endsWith(" tasks") ? region(norm) : null;
                if (section != null) {
                    if (area != null && area != section) return null;
                    area = section; continue;
                }
                Matcher header = HEADING.matcher(norm);
                if (header.matches()) {
                    if (area == null) continue;
                    int slot = List.of(TIERS).indexOf(header.group(1));
                    if (slot <= tier || raw.containsKey(slot)) return null;
                    tier = slot; raw.put(tier, new ArrayList<>());
                    afterReward = false; continue;
                }
                if (area == null || tier < 0 || afterReward || invalid.contains(tier)) continue;
                if (norm.startsWith("if i ever lose my ") || norm.equals("rewards") || norm.startsWith("rewards ")) {
                    afterReward = true; continue;
                }
                List<Task> tasks = raw.get(tier);
                if (tasks.size() > 30 || line.text.length() > 450 || tasks.isEmpty() && line.text.startsWith("(")
                    || layout == Layout.NATIVE && !line.explicitStyle) {
                    invalid.add(tier);continue;
                }
                if (!tasks.isEmpty() && continues(tasks.get(tasks.size()-1), line, layout)) {
                    Task prior = tasks.get(tasks.size()-1);
                    // A mixed-status fragment cannot change a parent row’s completion.
                    if (!line.text.startsWith("(") && prior.complete != line.complete || prior.text.length()+line.text.length()+1 > 450) {
                        invalid.add(tier);continue;
                    }
                    tasks.set(tasks.size()-1,new Task(prior.text+" "+line.text,prior.complete));
                } else tasks.add(line);
            }
        }
        return area == null ? null : new Attempt(area,raw,invalid);
    }

    private static boolean valid(Area area, int tier, List<Task> tasks, IntUnaryOperator varbit) {
        return tasks.size() == area.expected[tier]
            && tasks.stream().map(t -> normalize(t.text)).distinct().count() == tasks.size()
            && tasks.stream().filter(t -> t.complete).count() == varbit.applyAsInt(area.countVars[tier]);
    }

    private static boolean continues(Task previous, Task next, Layout layout) {
        char c = next.text.charAt(0);
        if (c == '(' || Character.isLowerCase(c) || ",.;:)]".indexOf(c) >= 0) return true;
        // Full sentences (including an optional trailing requirement) delimit tasks.
        String a = previous.text;
        if (a.matches("(?s).*[.!?)]$") || previous.complete != next.complete) return false;
        if (layout == Layout.LEGACY_MERGE) return true;
        if (layout != Layout.NATIVE) return false;
        String[] words = next.text.split("[^A-Za-z]+", 2);
        // The game pre-wraps tasks, including between a verb phrase and a proper name.
        // Require a long unpunctuated preceding line as well as a non-task opener.
        String last = a.substring(a.lastIndexOf(' ') + 1);
        return !last.isEmpty() && a.length() >= 40 && !TASK_STARTS.contains(words[0].toLowerCase(Locale.ROOT));
    }

    private static Area region(String heading) {
        String name = heading.replaceFirst(" (?:area )?(?:diary )?tasks$", "").replace(" and ", " ").trim();
        for (Area area : AREAS) {
            if (name.equals(normalize(area.name)) || name.equals(normalize(area.shortName))) return area;
        }
        return null;
    }

    private static List<Task> lines(String widget, boolean nativeStyle) {
        List<Task> output = new ArrayList<>();
        Matcher m = TOKEN.matcher(widget);
        StringBuilder line = new StringBuilder();
        boolean strike = false, hit = false, explicit = false, requirement = false;
        int end = 0;
        while (m.find()) {
            String text = widget.substring(end, m.start());
            if (!requirement && !text.isBlank()) hit |= strike;
            line.append(text);
            String tag = m.group().toLowerCase(Locale.ROOT);
            // A white parenthesis starts a requirement annotation. The game
            // strikes fulfilled skill/quest requirements even on unfinished tasks.
            // Preserve their display text, but do not use their strike state.
            if (tag.equals("<col=ffffff>") && widget.substring(m.end()).stripLeading().startsWith("(")) {
                requirement = true;
                explicit = true;
            }
            else if (tag.startsWith("<str") && !requirement) { strike = true; explicit = true; }
            else if (tag.equals("</str>") && !requirement) strike = false;
            else if (nativeStyle && tag.equals("<col=000000>") && line.toString().isBlank() && !explicit) {
                strike = false;
                explicit = true;
            }
            else if (tag.startsWith("<br") || !tag.startsWith("<")) {
                add(output, line, hit, explicit); hit = false; explicit = false;
                if (requirement) strike = false;
                requirement = false;
                if (nativeStyle) strike = false;
            }
            end = m.end();
        }
        String text = widget.substring(end);
        if (!requirement && !text.isBlank()) hit |= strike;
        line.append(text); add(output, line, hit, explicit);
        return output;
    }

    private static void add(List<Task> output, StringBuilder line, boolean strike, boolean explicit) {
        String text = clean(line.toString());
        if (!text.isBlank()) output.add(new Task(text, strike, explicit));
        line.setLength(0);
    }

    private static String clean(String text) {
        return text == null ? "" : text.replaceAll("<[^>]{1,100}>", "").replace(' ', ' ').replaceAll("\\s+", " ").trim();
    }

    private static String normalize(String text) {
        return text.toLowerCase(Locale.ROOT).replace('&', ' ').replaceAll("[^a-z0-9]+", " ").trim();
    }
}

