// commit 4cb0f9a2 under BSD-2-Clause. See LICENSE-ProgressScape.
package com.localprogressnotes;

import com.google.gson.JsonObject;
import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Varbits;
import net.runelite.api.gameval.VarPlayerID;

final class GameProgress {
    private static final int[] CA_TIER_ENUMS = { 3981, 3982, 3983, 3984, 3985, 3986 };
    private static final String[] CA_TIER_LABELS = { "Easy", "Medium", "Hard", "Elite", "Master", "Grandmaster" };
    private static final int CA_PARAM_TASK_ID = 1306;
    private static final int CA_PARAM_TASK_NAME = 1308;
    private static final int[] CA_TASK_VARPS = {
            VarPlayerID.CA_TASK_COMPLETED_0,  VarPlayerID.CA_TASK_COMPLETED_1,
            VarPlayerID.CA_TASK_COMPLETED_2,  VarPlayerID.CA_TASK_COMPLETED_3,
            VarPlayerID.CA_TASK_COMPLETED_4,  VarPlayerID.CA_TASK_COMPLETED_5,
            VarPlayerID.CA_TASK_COMPLETED_6,  VarPlayerID.CA_TASK_COMPLETED_7,
            VarPlayerID.CA_TASK_COMPLETED_8,  VarPlayerID.CA_TASK_COMPLETED_9,
            VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
            VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13,
            VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
            VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
            VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
            VarPlayerID.CA_TASK_COMPLETED_20,
    };

    static void appendCombatAchievements(Client client, JsonObject snapshot)
    {
        JsonArray completed = new JsonArray();
        JsonArray tasks = new JsonArray();
        Set<Integer> seen = new HashSet<>();
        int[] completedBits = new int[CA_TASK_VARPS.length];
        for (int i = 0; i < completedBits.length; i++) completedBits[i] = client.getVarpValue(CA_TASK_VARPS[i]);

        for (int tier = 0; tier < CA_TIER_ENUMS.length; tier++)
        {
            var tierEnum = client.getEnum(CA_TIER_ENUMS[tier]);
            if (tierEnum == null || tierEnum.getIntVals() == null) throw new IllegalStateException("Combat achievements not ready");
            for (int structId : tierEnum.getIntVals())
            {
                var struct = client.getStructComposition(structId);
                if (struct == null) continue;
                String name = struct.getStringValue(CA_PARAM_TASK_NAME);
                int id = struct.getIntValue(CA_PARAM_TASK_ID);
                if (name == null || name.isBlank() || id < 0 || !seen.add(id)) continue;
                JsonObject task = new JsonObject();
                task.addProperty("name", name);
                task.addProperty("tier", CA_TIER_LABELS[tier]);
                int varpIndex = id / 32;
                if (varpIndex >= completedBits.length) {
                    task.add("complete", JsonNull.INSTANCE);
                } else {
                    boolean done = (completedBits[varpIndex] & (1 << (id % 32))) != 0;
                    task.addProperty("complete", done);
                    if (done) completed.add(name);
                }
                tasks.add(task);
            }
        }
        snapshot.add("combat_achievements_complete", completed);
        snapshot.add("combat_achievement_tasks", tasks);
    }

    static JsonObject buildDiaries(Client client)
    {
        JsonObject diaries = new JsonObject();

        int[][] diaryVarbits = {
                { Varbits.DIARY_ARDOUGNE_EASY,   Varbits.DIARY_ARDOUGNE_MEDIUM,   Varbits.DIARY_ARDOUGNE_HARD,   Varbits.DIARY_ARDOUGNE_ELITE },
                { Varbits.DIARY_DESERT_EASY,     Varbits.DIARY_DESERT_MEDIUM,     Varbits.DIARY_DESERT_HARD,     Varbits.DIARY_DESERT_ELITE },
                { Varbits.DIARY_FALADOR_EASY,    Varbits.DIARY_FALADOR_MEDIUM,    Varbits.DIARY_FALADOR_HARD,    Varbits.DIARY_FALADOR_ELITE },
                { Varbits.DIARY_FREMENNIK_EASY,  Varbits.DIARY_FREMENNIK_MEDIUM,  Varbits.DIARY_FREMENNIK_HARD,  Varbits.DIARY_FREMENNIK_ELITE },
                { Varbits.DIARY_KANDARIN_EASY,   Varbits.DIARY_KANDARIN_MEDIUM,   Varbits.DIARY_KANDARIN_HARD,   Varbits.DIARY_KANDARIN_ELITE },
                { Varbits.DIARY_KARAMJA_EASY,    Varbits.DIARY_KARAMJA_MEDIUM,    Varbits.DIARY_KARAMJA_HARD,    Varbits.DIARY_KARAMJA_ELITE },
                { Varbits.DIARY_KOUREND_EASY,    Varbits.DIARY_KOUREND_MEDIUM,    Varbits.DIARY_KOUREND_HARD,    Varbits.DIARY_KOUREND_ELITE },
                { Varbits.DIARY_LUMBRIDGE_EASY,  Varbits.DIARY_LUMBRIDGE_MEDIUM,  Varbits.DIARY_LUMBRIDGE_HARD,  Varbits.DIARY_LUMBRIDGE_ELITE },
                { Varbits.DIARY_MORYTANIA_EASY,  Varbits.DIARY_MORYTANIA_MEDIUM,  Varbits.DIARY_MORYTANIA_HARD,  Varbits.DIARY_MORYTANIA_ELITE },
                { Varbits.DIARY_VARROCK_EASY,    Varbits.DIARY_VARROCK_MEDIUM,    Varbits.DIARY_VARROCK_HARD,    Varbits.DIARY_VARROCK_ELITE },
                { Varbits.DIARY_WESTERN_EASY,    Varbits.DIARY_WESTERN_MEDIUM,    Varbits.DIARY_WESTERN_HARD,    Varbits.DIARY_WESTERN_ELITE },
                { Varbits.DIARY_WILDERNESS_EASY, Varbits.DIARY_WILDERNESS_MEDIUM, Varbits.DIARY_WILDERNESS_HARD, Varbits.DIARY_WILDERNESS_ELITE },
        };

        String[] diaryNames = {
                "Ardougne", "Desert", "Falador", "Fremennik", "Kandarin",
                "Karamja", "Kourend & Kebos", "Lumbridge & Draynor",
                "Morytania", "Varrock", "Western Provinces", "Wilderness"
        };

        for (int i = 0; i < diaryNames.length; i++)
        {
            JsonObject tiers = new JsonObject();
            tiers.addProperty("easy",   client.getVarbitValue(diaryVarbits[i][0]) == 1);
            tiers.addProperty("medium", client.getVarbitValue(diaryVarbits[i][1]) == 1);
            tiers.addProperty("hard",   client.getVarbitValue(diaryVarbits[i][2]) == 1);
            tiers.addProperty("elite",  client.getVarbitValue(diaryVarbits[i][3]) == 1);
            diaries.add(diaryNames[i], tiers);
        }

        return diaries;
    }

}

package com.localprogressnotes;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.Locale;
import net.runelite.client.util.Filepath;

final class LocalExport {
    private final Gson json;

    LocalExport(Gson gson) {
        json = gson.newBuilder().serializeNulls().setPrettyPrinting().create();
    }

    private static String characterKey(String character) {
        String name = character.replace('\u00a0', ' ').strip();
        if (!name.matches("[A-Za-z0-9 _-]{1,12}")) {
            throw new IllegalArgumentException("Unexpected character name");
        }
        return name.toLowerCase(Locale.ROOT).replace('_', ' ').replace('-', ' ');
    }

    private static String snapshotKey(String character, JsonObject data) {
        String key = characterKey(character);
        if (!data.has("profile_mode")) return key;
        String mode = data.get("profile_mode").getAsString();
        if (!mode.matches("[A-Z_]{1,30}")) throw new IllegalArgumentException("Unexpected game mode");
        return mode.equals("STANDARD") ? key : key + "--" + mode.toLowerCase(Locale.ROOT);
    }

    Filepath write(Filepath root, String character, JsonObject data) throws IOException {
        return atomicWrite(root, "progress-" + snapshotKey(character, data) + ".json", json.toJson(data) + "\n");
    }

    Filepath writeDashboard(Filepath root, String character, JsonObject data) throws IOException {
        String key = snapshotKey(character, data);
        String template;
        try (InputStream resource = LocalExport.class.getResourceAsStream("/local-progress-dashboard.html")) {
            if (resource == null) throw new IOException("Dashboard template missing");
            template = new String(resource.readAllBytes(), StandardCharsets.UTF_8);
        }
        String prefix = "<script type=\"application/json\" id=\"embedded-data\">";
        String suffix = "</script>";
        String marker = prefix + "null" + suffix;
        int pos = template.indexOf(marker);
        if (pos < 0 || pos != template.lastIndexOf(marker)) throw new IOException("Invalid dashboard template");
        // Gson escapes HTML-sensitive characters by default. Also guarantee no literal '<'
        // in the payload so an imported string cannot close the inert script element.
        String payload = json.toJson(data).replace("<", "\\u003c");
        String html = template.substring(0, pos) + prefix + payload + suffix + template.substring(pos + marker.length());
        return atomicWrite(root, "dashboard-" + key + ".html", html);
    }

    private static Filepath atomicWrite(Filepath root, String filename, String body) throws IOException {
        root.createDirectories();
        Filepath target = root.joinSegment(filename);
        Filepath tmp = root.createTempFile(".progress-", ".tmp");
        try {
            tmp.write(body.getBytes(StandardCharsets.UTF_8));
            try {
                tmp.moveTo(target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            } catch (AtomicMoveNotSupportedException ignored) {
                tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
            }
            return target;
        } finally {
            tmp.deleteIfExists();
        }
    }
}

