        check(page != null && page.area.name.equals("Ardougne"),"Ardougne page accepted");
        JsonArray rows = page.current(v -> 9).getAsJsonArray("hard");
        check(rows.size()==12,"twelve tasks");
        check(rows.get(3).getAsJsonObject().get("text").getAsString().contains("monkey cage"),"wrapped row joins");
        check(rows.get(3).getAsJsonObject().get("complete").getAsBoolean(),"strikethrough recognized");
        check(!rows.get(7).getAsJsonObject().get("complete").getAsBoolean(),"plain berry row not complete");
        check(page.current(v -> 10).size()==0,"later changed count invalidates stale tier");
        check(DiaryJournal.parse("Desert Treasure II",widgets,v -> 9)==null,"quest journal rejected");
        check(DiaryJournal.parse("Achievement Diary - Desert",widgets,v -> 9)==null,"mismatched regions rejected");
        check(DiaryJournal.parse(title,widgets.subList(0,widgets.size()-3),v -> 9)==null,"truncated tier rejected");
        check(DiaryJournal.parse(title,widgets,v -> 8)==null,"wrong completed count rejected");
        List<String> bad=new ArrayList<>(widgets);bad.set(12,bad.get(11));
        check(DiaryJournal.parse(title,bad,v -> 9)==null,"duplicate text rejected");
        List<String> bare = new ArrayList<>();
        bare.add("LUMBRIDGE AND DRAYNOR DIARY TASKS");
        bare.add("Easy Diary Tasks (6/12)");
        for (int n=0;n<12;n++) {
            String task="Visit location "+(n+1);
            bare.add(n<6?"<str>"+task+"</str>":task);
        }
        DiaryJournal.Frame lum = new DiaryJournal.Frame("Achievement Diary – Lumbridge and Draynor",List.of(bare));
        DiaryJournal.Result lumRead = DiaryJournal.analyze(lum,v -> 6);
        check(lumRead.page!=null && lumRead.page.current(v -> 6).getAsJsonArray("easy").size()==12,
            "unpunctuated rows, expanded tier headers and ampersand aliases");
        List<String> badEasy=new ArrayList<>(widgets);
        badEasy.add(1,"Easy Tasks");badEasy.add(2,"(an orphan fragment)");
        DiaryJournal.Result recovery=DiaryJournal.analyze(new DiaryJournal.Frame(title,List.of(badEasy)),v -> 9);
        check(recovery.page!=null&&recovery.page.tiers.containsKey(2),"unreadable tier does not discard good tier");
        check(recovery.diagnostic.contains("easy unclear"),"diagnostic isolates invalid tier");
