        check(desertRows.size() == 10 && !desertRows.get(1).getAsJsonObject().get("complete").getAsBoolean(), "unclosed strike must not leak to next task");
        check(DiaryJournal.parse("Achievement Diary - Desert", desert, v -> 3) == null, "wrong count still rejected");
        desertJournalReplay();
        System.out.println("PASS: diary title, wraps, strike states, region ownership, counts, partial/stale/duplicate rejection, alternate formatting, native wrap and strike regressions, and passive capture gates.");
    }
    private static void desertJournalReplay() throws Exception {
        // Real formatting, with task completion states changed for the public fixture.
        List<String> capture;
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            DiaryJournalTest.class.getResourceAsStream("/desert-journal.txt"), StandardCharsets.UTF_8))) {
            capture = reader.lines().collect(Collectors.toList());
        }
        IntUnaryOperator count = v -> v == VarbitID.DESERT_EASY_COUNT || v == VarbitID.DESERT_MED_COUNT
            || v == VarbitID.DESERT_HARD_COUNT ? 4 : 0;
        List<String> widgets = capture.subList(1, capture.size());
        com.google.gson.JsonObject exportedTiers = null;
        for (List<String> input : List.of(widgets, List.of(String.join("<br>", widgets)))) {
            DiaryJournal.Result replay = DiaryJournal.analyze(new DiaryJournal.Frame(capture.get(0), List.of(input)), count);
            check(replay.page != null && replay.page.tiers.size() == 4, "Desert replay: " + replay.diagnostic);
            com.google.gson.JsonObject export = replay.page.current(count);
            exportedTiers = export;
            String[] tiers = {"easy", "medium", "hard", "elite"};
            String[] states = {"10011000001", "100110000100", "0101101000", "000000"};
            for (int t = 0; t < tiers.length; t++) {
                JsonArray rows = export.getAsJsonArray(tiers[t]);
                check(rows.size() == states[t].length(), "Desert replay row count " + tiers[t]);
                for (int row = 0; row < rows.size(); row++) {
                    check(rows.get(row).getAsJsonObject().get("complete").getAsBoolean() == (states[t].charAt(row) == '1'),
                        "Desert replay checkmark " + tiers[t] + " row " + (row + 1));
                }
            }
            check(export.getAsJsonArray("easy").get(8).getAsJsonObject().get("text").getAsString()
                .contains("Pyramid Plunder."), "Desert replay uppercase wrap");
            check(export.getAsJsonArray("hard").get(2).getAsJsonObject().get("text").getAsString()
                .contains("(68 Magic, Dream Mentor)"), "Desert replay separate requirement row retained");
            check(export.getAsJsonArray("elite").get(4).getAsJsonObject().get("text").getAsString()
                .contains("Pyramid Plunder."), "Desert replay Elite uppercase wrap");
        }
        if (System.getProperty("diaryReplayOutput") != null) {
            Path output = Path.of(System.getProperty("diaryReplayOutput"));
            Files.createDirectories(output.getParent());
            Files.writeString(output, exportedTiers.toString());
        }
        System.out.println("PASS: representative Desert diary; exact ordered checkmarks for all 39 tasks and four exported tiers.");
    }
    private static void check(boolean passed,String label){if(!passed)throw new AssertionError(label);}
}

