public final class ExportTest {
    private static void require(boolean ok, String message) {
        if (!ok) throw new AssertionError(message);
    }

    private static String read(Filepath file) throws Exception {
        try (var input = file.openInputStream()) {
            return new String(input.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
        }
    }

    public static void main(String[] args) throws Exception {
        Path path = Files.createTempDirectory("local-progress-export-test");
        Filepath dir = Filepath.Unchecked.getRooted(path);
        LocalExport writer = new LocalExport(new Gson());
        try {
            require(DashboardActions.latest(dir) == null, "Empty folder has no dashboard");
            JsonObject input = new JsonObject();
            input.addProperty("quest_points", 297);
            Filepath first = writer.write(dir, "Demo Main", input);
            require(first.getParent().equals(dir), "Incorrect directory");
            require(new Gson().fromJson(read(first), JsonObject.class)
                .get("quest_points").getAsInt() == 297, "Wrong payload");
            input.addProperty("quest_points", 300);
            Filepath second = writer.write(dir, "Demo Alt", input);
            require(!second.equals(first), "Characters not separated");
            require(writer.write(dir, "demo_main", input).equals(first), "Same character not matched");
            require(read(first).contains("300"), "Latest snapshot not saved");
            try {
                writer.write(dir, "../escape", input);
                throw new AssertionError("Path injection was accepted");
            } catch (IllegalArgumentException expected) {
                // Expected rejection.
            }
            input.addProperty("probe", "</script><img src=x>");
            Filepath dash = writer.writeDashboard(dir, "Demo Main", input);
            String html = read(dash);
            require(html.contains("dashboard") && !html.contains("</script><img src=x>"), "Unsafe dashboard interpolation");
            require(html.contains("quest_points") && html.contains("300"), "Dashboard embedding missing");
            require(!dash.equals(first) && dash.getParent().equals(dir), "Incorrect dashboard path");
            require(dash.equals(DashboardActions.latest(dir)), "Existing saved dashboard not discoverable");
            input.addProperty("profile_mode", "BETA");
            Filepath beta = writer.write(dir, "Demo Main", input);
            require(!first.equals(beta) && beta.toString().endsWith("--beta.json"), "Modes not separated");
            try (var files = Files.list(path)) {
                require(files.count() == 4, "Extra temporary files");
            }
            Filepath modeDash = writer.writeDashboard(dir, "Demo Alt", input);
            Files.setLastModifiedTime(path.resolve(dash.getFileName()), FileTime.fromMillis(1000));
            Files.setLastModifiedTime(path.resolve(modeDash.getFileName()), FileTime.fromMillis(2000));
            Files.writeString(path.resolve("dashboard-invalid🚫.html"), "Not a dashboard");
            Files.createDirectory(path.resolve("dashboard-test.html"));
            require(modeDash.equals(DashboardActions.latest(dir)), "Open and Copy must select the most recent valid HTML");
            modeDash.delete();
            require(dash.equals(DashboardActions.latest(dir)), "Deleted latest file falls back to existing dashboard");
        } finally {
            try (var files = Files.list(path)) {
                for (Path file : (Iterable<Path>) files::iterator) Files.delete(file);
            }
            Files.delete(path);
        }
        System.out.println("PASS: JSON, separate characters, safe filenames, replacement, cleanup, and dashboard discovery after restart");
    }
}
